from zipfile import ZipFile, ZIP_DEFLATED
from lxml import etree
from docx import Document
from pathlib import Path
src=Path('documents/technova-ai-vendor-agreement-draft-2-redline.docx')
out=Path('clean-base.docx')
ns={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
with ZipFile(src) as zin:
    files={n:zin.read(n) for n in zin.namelist()}
xml=etree.fromstring(files['word/document.xml'])
# Accept insertions, reject deletion nodes by moving children / removing
for parent in xml.xpath('.//w:ins', namespaces=ns):
    p=parent.getparent(); idx=p.index(parent)
    for child in list(parent):
        p.insert(idx, child); idx+=1
    p.remove(parent)
for node in xml.xpath('.//w:del | .//w:moveFrom', namespaces=ns):
    p=node.getparent(); p.remove(node)
files['word/document.xml']=etree.tostring(xml, xml_declaration=True, encoding='UTF-8', standalone='yes')
with ZipFile(out,'w',ZIP_DEFLATED) as zout:
    for n,b in files.items(): zout.writestr(n,b)
d=Document(out)
with open('clean-paragraphs.txt','w') as f:
 for i,p in enumerate(d.paragraphs):
  t=p.text.replace('\n',' ')
  if t.strip(): f.write(f'{i}\t{t}\n')
print('saved',out,'paras',len(d.paragraphs))
