from pathlib import Path
from zipfile import ZipFile,ZIP_DEFLATED
from lxml import etree
import re
from docx import Document
from docx.shared import Inches,Pt,RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.enum.section import WD_ORIENT
from docx.enum.table import WD_TABLE_ALIGNMENT,WD_CELL_VERTICAL_ALIGNMENT
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
R=Path('.'); SRC=R/'documents/technova-ai-vendor-agreement-draft-2-redline.docx'; CLEAN=R/'accepted-draft2-clean.docx'; OUT=R/'output'; OUT.mkdir(exist_ok=True)
W='http://schemas.openxmlformats.org/wordprocessingml/2006/main'; ns={'w':W}
def paras(d):
 out=list(d.paragraphs)
 for t in d.tables:
  for row in t.rows:
   for c in row.cells: out+=list(c.paragraphs)
 return out
def clean(s):
 old=None
 while old!=s:
  old=s; s=re.sub(r'\[DELETED:\s*([^\]]*)\]','',s); s=re.sub(r'\[ADDED:\s*([^\]]*)\]',r'\1',s)
 s=s.replace('### ','').replace('## ','').replace('Platformand','Platform and').replace('non-transferable(except','non-transferable (except')
 s=re.sub(r'\s{2,}',' ',s); return s.strip()
def plain(p,text):
 for x in list(p._p):
  if x.tag!=qn('w:pPr'): p._p.remove(x)
 if text:
  r=OxmlElement('w:r'); t=OxmlElement('w:t'); t.text=text
  if text[:1].isspace() or text[-1:].isspace(): t.set('{http://www.w3.org/XML/1998/namespace}space','preserve')
  r.append(t); p._p.append(r)
def accept():
 with ZipFile(SRC) as z: fs={n:z.read(n) for n in z.namelist()}
 x=etree.fromstring(fs['word/document.xml'])
 for n in list(x.xpath('.//w:ins',namespaces=ns)):
  p=n.getparent(); i=p.index(n)
  for ch in list(n): p.insert(i,ch); i+=1
  p.remove(n)
 for n in list(x.xpath('.//w:del | .//w:moveFrom',namespaces=ns)): n.getparent().remove(n)
 fs['word/document.xml']=etree.tostring(x,xml_declaration=True,encoding='UTF-8',standalone='yes')
 with ZipFile(CLEAN,'w',ZIP_DEFLATED) as z:
  for n,b in fs.items(): z.writestr(n,b)
 d=Document(CLEAN)
 for p in paras(d):
  txt=''.join((e.text or '') for e in p._p.xpath('.//w:t | .//w:delText',namespaces=ns)) or p.text
  plain(p,clean(txt))
 d.save(CLEAN)
def run(parent,text,kind):
 r=OxmlElement('w:r'); rp=OxmlElement('w:rPr'); c=OxmlElement('w:color'); c.set(qn('w:val'),'C00000'); rp.append(c)
 if kind=='del': rp.append(OxmlElement('w:strike')); tag='w:delText'
 else: u=OxmlElement('w:u'); u.set(qn('w:val'),'single'); rp.append(u); tag='w:t'
 r.append(rp); t=OxmlElement(tag); t.text=text
 if text[:1].isspace() or text[-1:].isspace(): t.set('{http://www.w3.org/XML/1998/namespace}space','preserve')
 r.append(t); parent.append(r)
def track(p,new,old=None):
 old=p.text if old is None else old
 for x in list(p._p):
  if x.tag!=qn('w:pPr'): p._p.remove(x)
 for typ,txt,tag in [('del',old,'w:del'),('ins',new,'w:ins')]:
  e=OxmlElement(tag); e.set(qn('w:author'),'Kirkstead & Yao'); e.set(qn('w:date'),'2025-05-14T17:00:00Z'); run(e,txt,typ); p._p.append(e)
def find(d,start=None,contains=None):
 for p in d.paragraphs:
  if start and p.text.strip().startswith(start): return p
  if contains and contains in p.text: return p
 raise RuntimeError('not found '+str(start or contains))
def rep(d,start,new):
 p=find(d,start=start); track(p,new); return p
def after(p,text,style=None):
 q=OxmlElement('w:p')
 if style:
  pp=OxmlElement('w:pPr'); ps=OxmlElement('w:pStyle'); ps.set(qn('w:val'),style); pp.append(ps); q.append(pp)
 e=OxmlElement('w:ins'); e.set(qn('w:author'),'Kirkstead & Yao'); e.set(qn('w:date'),'2025-05-14T17:00:00Z'); run(e,text,'ins'); q.append(e); p._p.addnext(q); return q
def note(d,anchor,text): after(find(d,start=anchor),text,'Normal')
def celltrack(c,new): track(c.paragraphs[0],new,c.text)
def build():
 d=Document(CLEAN)
 after(d.paragraphs[4],'DRAFT 3 REDLINE — May 14, 2025 — New changes tracked against the clean, accepted Draft 2 base.','Title')
 note(d,'Right-click to update Table of Contents','DRAFTING NOTES — NOT PART OF THE AGREEMENT (remove before execution): OPEN — AI-output indemnity; general liability cap; broadened IP indemnity scope; de-identified/aggregated data certification; governing law/dispute resolution; SLA credit cap; accuracy ramp; and escrow scope/agent. Yellow-zone cautions: 450 ms latency for LendStream real-time decisioning and $5,000,000 Tech E&O. Fallbacks are described in the companion updated issues list.')
 rep(d,'"Customer-Trained Adaptations"','"Customer-Trained Adaptations" means all fine-tuned weights, adapter layers (including without limitation low-rank adaptation ("LoRA") matrices), prompt-tuning parameters, and any other derivative model parameters generated through training, fine-tuning, or adaptation of the Base Model using Customer Data or Customer-specific datasets. As between the Parties, Vendor owns the Customer-Trained Adaptations, subject to the irrevocable, perpetual, royalty-free license granted in Section 5.2 and the portability, escrow, and non-assertion rights set forth therein.')
 rep(d,'"Escrow Materials"','"Escrow Materials" means the fine-tuned adapter weights comprising the Customer-Trained Adaptations, together with all training configuration files and pipeline artifacts necessary to render those adapter weights usable for Customer’s authorized LendStream use, as more particularly described in Section 5A.2. Escrow Materials exclude Base Model source code and Meridian’s general-purpose proprietary training infrastructure.')
 rep(d,'Section 5.2 —','Section 5.2 — License to Customer-Trained Adaptations')
 rep(d,'As between the Parties, Customer is and shall','As between the Parties, Vendor retains all right, title, and interest in and to the Customer-Trained Adaptations, including all fine-tuned weights, adapter layers, LoRA matrices, and other model parameters generated through fine-tuning the Base Model using Customer Data. Vendor grants Customer an irrevocable, perpetual, worldwide, royalty-free, fully paid-up license to use, reproduce, modify, deploy, and further develop the Customer-Trained Adaptations for Customer’s internal business purposes and in connection with LendStream, including after expiration or termination. The license survives termination and is not conditioned on additional fees. [ALTERNATIVE — Customer reserves its position that Customer should own the Customer-Trained Adaptations outright, with Vendor retaining ownership of the Base Model and pre-existing platform IP.]')
 rep(d,'Vendor is granted a limited','Customer may exercise the foregoing license after termination or expiration by exporting the Customer-Trained Adaptations through Vendor’s API in an industry-standard format, including ONNX, SafeTensors, or a mutually agreed equivalent. Vendor shall complete the export within thirty (30) days after termination or expiration, without additional charge. Vendor shall not assert any patent, copyright, trade secret, trademark, or other Intellectual Property Right against Customer’s use, deployment, modification, or further development of the exported Customer-Trained Adaptations, including post-termination use, and shall cause this covenant to bind successors and assignees.')
 rep(d,'Within thirty (30) days of the Effective Date','Within thirty (30) days of the Effective Date, Vendor shall enter into a three-party technology escrow agreement with Customer and Iron Mountain Intellectual Property Management, Inc. (the “Escrow Agent”), in a form reasonably satisfactory to Customer, pursuant to which Vendor shall deposit and maintain the Escrow Materials. If Vendor insists on NCC Group plc, Customer will consider NCC Group as an acceptable fallback agent, subject to confirmation of equivalent AI/ML escrow capability.')
 rep(d,'Vendor shall deposit and maintain current versions','Vendor shall deposit and maintain current versions of: (a) all production fine-tuned adapter weights comprising Customer-Trained Adaptations; (b) training configuration files, including hyperparameters and training scripts; and (c) pipeline artifacts necessary to render the adapter weights usable and to redeploy the fine-tuned model for Customer’s authorized LendStream use, including inference code, model-serving configuration, dependency specifications, and deployment documentation. The Escrow Materials do not include Base Model source code, Base Model weights, or proprietary training infrastructure not specific to Customer’s adapter weights.')
 rep(d,'Vendor shall update the Escrow Materials within thirty','Vendor shall update the Escrow Materials quarterly and within thirty (30) days after any material model-version update, and each deposit shall include a manifest and integrity checksums.')
 rep(d,'The Escrow Agent shall release the Escrow Materials','The Escrow Agent shall release the Escrow Materials to Customer upon: (a) Vendor’s insolvency, including any voluntary or involuntary bankruptcy, insolvency, receivership, liquidation, or similar proceeding, or an assignment for the benefit of creditors; (b) a material breach remaining uncured for more than sixty (60) days after Customer’s written notice; or (c) Vendor’s cessation of support, maintenance, or commercial availability of the MeridianIQ Platform. Upon release, Customer shall receive a non-exclusive, irrevocable, perpetual, royalty-free, worldwide license to use, modify, compile, deploy, and maintain the released Escrow Materials for internal business purposes and LendStream.')
 rep(d,'Upon release, Customer shall receive a non-exclusive','Upon release, Customer shall receive a non-exclusive, irrevocable, perpetual, royalty-free, worldwide license to use, modify, compile, deploy, and maintain the released Escrow Materials for internal business purposes and LendStream.')
 rep(d,'Customer shall have the right, no more than once per Contract Year','Customer shall have the right, no more than once per Contract Year, to request Level 2 verification by the Escrow Agent or a mutually agreed technical expert that the Escrow Materials are complete, current, readable, and sufficient to render the adapter weights usable for the authorized LendStream deployment. Vendor shall cooperate. Customer bears verification cost unless a material deficiency is found, in which case Vendor bears the cost.')
 rep(d,'Vendor shall process Customer Data solely for the','Vendor shall process Customer Data solely to provide the Platform and perform Vendor’s obligations. Vendor shall not sell Customer Data or use Customer Data, including de-identified or aggregated data, to train, improve, benchmark, or develop any model, product, or service for Vendor or a third party, except that Vendor may use de-identified or aggregated data for model improvement only if (a) it meets Cal. Civ. Code § 1798.140(m), including safeguards against re-identification and inadvertent release, and (b) an independent third-party assessor approved in writing by Customer verifies the de-identification in writing before any use. This is a specific contractual obligation, not merely a representation or warranty.')
 rep(d,'In the event of any confirmed or reasonably suspected security breach','In the event of any confirmed or reasonably suspected security breach involving unauthorized access, acquisition, use, or disclosure of Customer Data (a “Security Breach”), Vendor shall notify Customer within seventy-two (72) hours after Vendor first discovers or becomes aware of the Security Breach, whether or not its scope or cause is confirmed; promptly investigate, contain, mitigate, and remediate; provide reasonably detailed information; and cooperate with Customer’s response and notification obligations.')
 rep(d,'Vendor shall maintain API response latency','Vendor shall maintain API response latency at or below four hundred fifty (450) milliseconds at the ninety-fifth percentile (p95 ≤ 450 ms) during each calendar month, measured at the Platform API gateway from receipt to response. [DRAFTING NOTE — YELLOW-ZONE CAUTION: Product Engineering prefers sub-400 ms for LendStream real-time decisioning; revisit at the May 19 joint call.]')
 rep(d,'Vendor shall maintain model accuracy','Vendor shall maintain model accuracy, measured by F1 score against the mutually agreed validation dataset, at or above 0.92 during the ninety-day Stabilization Period from October 1, 2025 through December 31, 2025, and at or above 0.94 beginning January 1, 2026. The validation dataset and methodology shall be documented in the SOW and reviewed at least annually.')
 rep(d,'During the Stabilization Period','During the Stabilization Period (October 1, 2025 through December 31, 2025), Vendor shall meet F1 ≥ 0.92. Beginning January 1, 2026, Vendor shall meet F1 ≥ 0.94. Service Credits shall accrue for accuracy failures during stabilization if F1 is below 0.92.')
 rep(d,'In the event Vendor fails to meet the','In the event Vendor fails to meet the Uptime SLA, API Latency target, or Model Accuracy target, Customer shall receive Service Credits under Exhibit B. Credits apply automatically to the next invoice after the monthly service report, or, upon simple written notice within thirty (30) days, within fifteen (15) business days. The aggregate monthly credits shall not exceed twenty percent (20%) of the monthly Annual Platform Fee, equal to $40,000 per month; credits are not Customer’s sole remedy.')
 rep(d,' Service Credits shall be applied as a credit','Service Credits shall apply automatically to the next invoice after the monthly service report, or, on simple written notice, within fifteen (15) business days. If the Agreement ends with unapplied credits, Vendor shall refund them in cash within thirty (30) days. Credits are not Customer’s sole remedy, including the Section 9.5 termination right.')
 rep(d,'If Vendor fails to meet any SLA target','If Vendor fails to meet any material SLA target (Uptime, Latency, or Accuracy) for three (3) consecutive calendar months, Customer may terminate on thirty (30) days’ written notice without an early termination fee. Vendor shall refund prepaid Annual Platform Fees for the post-termination period and provide up to ninety (90) days’ transition assistance at no charge. [DRAFTING NOTE — OPEN: Meridian has not substantively responded.]')
 rep(d,'EXCEPT AS SET FORTH IN SECTION 10.3','EXCEPT AS SET FORTH IN SECTION 10.3, each Party’s total aggregate liability arising from this Agreement shall not exceed one and one-half times (1.5×) the Annual Platform Fee, equal to $3,600,000 (the “General Cap”). [DRAFTING NOTE — OPEN: compromise between TechNova’s $4.8M and Meridian’s $2.4M.]')
 rep(d,'Section 10.3 —','Section 10.3 — Uncapped and Super-Capped Carve-Outs')
 rep(d,'The General Cap set forth','The General Cap and consequential-damages exclusion shall not apply to: (a) willful misconduct or gross negligence, fully uncapped; (b) breach of Article 7, uncapped; (c) Vendor’s Article 6 data-breach liability, subject to a $7,200,000 super-cap; (d) Vendor’s indemnity obligations under Sections 11.1 and 11.2, subject to the same $7,200,000 super-cap; and (e) Customer payment obligations, uncapped. No cap applies to willful misconduct or gross negligence. [DRAFTING NOTE — PARTIALLY RESOLVED: Meridian accepted the 3× concept for IP indemnity and data breach; drafting remains open.]')
 rep(d,'Vendor shall defend, indemnify, and hold harmless Customer and','Vendor shall defend, indemnify, and hold harmless Customer, its Affiliates, and their officers, directors, employees, agents, and successors from third-party claims alleging that Customer’s authorized use of the Platform, Customer-Trained Adaptations, or related outputs infringes, misappropriates, or violates any Intellectual Property Right, and shall pay resulting damages, costs, and reasonable attorneys’ fees.')
 rep(d,"  Vendor shall have no indemnification obligation",'Vendor’s obligations cover all Intellectual Property Rights, including patents, copyrights, trademarks, trade secrets, moral rights, database rights, and analogous foreign rights, arising from authorized use. Exclusions are limited to claims caused solely by Customer modification other than as contemplated, material violation of the Agreement/Documentation/law, or a third-party combination where the claim would not otherwise arise. [DRAFTING NOTE — OPEN: Meridian Draft 1 was limited to registered U.S. patents and copyrights.]')
