  pp=OxmlElement('w:pPr'); ps=OxmlElement('w:pStyle'); ps.set(qn('w:val'),style); pp.append(ps); q.append(pp)
 e=OxmlElement('w:ins'); e.set(qn('w:author'),'Kirkstead & Yao'); e.set(qn('w:date'),'2025-05-14T17:00:00Z'); run(e,text,'ins'); q.append(e); p._p.addnext(q); return q
def note(d,anchor,text): after(find(d,start=anchor),text,'Normal')
